head.script:
scwin.onpageload = function () {
    scwin.init();
    let name = localStorage.getItem("selectedMenu") ?? "home";
    scwin.buttonFocus(name);
};


scwin.footer_button_onclick = function (e) {
    const id = e.target.id;
    const match = id.split("_");

    if (match && match[4]) {
        const name = match[4];
        scwin.selectedMenu = name;

        scwin.urlMove(name);
        localStorage.setItem("selectedMenu", name);
    }
};

scwin.buttonFocus = function (name) {
    const img = $p.getComponentById(name + "_img");
    const txt = $p.getComponentById(name + "_text");


    if (img) {
        img.setSrc(`/InsWebApp/images/mobile/${name}-orange.svg`);
    }

    if (txt) {
        txt.setStyle("color", "#FEB826");
    }
}

scwin.init = function () {
    let name = ["home", "project", "profile"];

    name.forEach((value) => {
        const img = $p.getComponentById(value + "_img");
        const txt = $p.getComponentById(value + "_text");
        img.setSrc(`/InsWebApp/images/mobile/${value}-gray.svg`);
        txt.setStyle("color", "#D9D9D9");
    })
}

scwin.urlMove = function (name) {
    switch (name) {
        case "project": $p.url("/InsWebApp/ui/mobile/taskPage.xml");
            break;
        case "profile": $p.url("/InsWebApp/ui/mobile/myPage.xml");
            break;
        case "home": $p.url("/InsWebApp/ui/mobile/mainPage.xml");
            break;
        default: $p.url("/InsWebApp/ui/mobile/mainPage.xml");
    }
}
